    // Function to compute sum of divisors of n
    private static long sumOfDivisors(long n) {
        long sum = 1;
        long temp = n;

        // Factor 2
        long p = 2;
        long power = 1;
        while (temp % p == 0) {
            temp /= p;
            power *= p;
            sum += power;
        }

        // Odd factors
        p = 3;
        while (p * p <= temp) {
            power = 1;
            boolean divided = false;
            while (temp % p == 0) {
                temp /= p;
                power *= p;
                divided = true;
            }
            if (divided) {
                sum *= (power * p - 1) / (p - 1);
            }
            p += 2;
        }

        // Remaining prime factor
        if (temp > 1) {
            sum *= (temp * temp - 1) / (temp - 1);
        }

        return sum;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long A = Long.parseLong(br.readLine().trim());

        long count = 0;

        // For each divisor d of A, consider x = A - d
        for (long d = 1; d * d <= A; d++) {
            if (A % d == 0) {
                long d1 = d;
                long x1 = A - d1;
                if (x1 > 0 && sumOfDivisors(x1) == A) {
                    count++;
                }

                long d2 = A / d;
                if (d2 != d1) {
                    long x2 = A - d2;
                    if (x2 > 0 && sumOfDivisors(x2) == A) {
                        count++;
                    }
                }
            }
        }

        System.out.println(count);
    }
