public class Main {
    // Compute gcd
    private static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long A = Long.parseLong(br.readLine().trim());

        long ans = 0;

        // We need to find all x such that sum of divisors of x equals A.
        // Using the known characterization:
        // For any x, let g = gcd(x, A). Then x/g is square-free and coprime with A/g.
        // Also, J(x) = J(g) * product over primes p|x/g of (1 + p).
        // We iterate over all divisors g of A and count valid x/g.

        // Enumerate divisors g of A
        long limit = (long) Math.sqrt(A);
        for (long d = 1; d <= limit; d++) {
            if (A % d == 0) {
                long g1 = d;
                long g2 = A / d;

                ans += countForG(g1, A);
                if (g2 != g1) ans += countForG(g2, A);
            }
        }

        System.out.println(ans);
    }

    // Count number of x such that gcd(x, A) = g and J(x) = A
    private static long countForG(long g, long A) {
        // J(g) must divide A
        long sigmaG = sigma(g);
        if (A % sigmaG != 0) return 0;
        long target = A / sigmaG;

        // We need to count square-free numbers y, gcd(y, A/g) = 1,
        // such that product over primes p|y of (1 + p) = target.
        // This is equivalent to factoring target into factors of form (1 + p),
        // where p is prime and p does not divide A/g, and each prime used at most once.
        // This is hard in general, but constraints are small enough for brute force
        // over divisors of target.

        // First, factor target into primes of form (1 + p) where p is prime.
        // But we don't know p directly. Instead, we find all primes p such that (1 + p) divides target.
        // For each divisor d of target, if d-1 is prime, then p = d-1.
        // Then we need to count subsets of these primes whose (1+p) product equals target,
        // and also p must be coprime with A/g.

        long Ag = A / g;
        // Collect candidate primes
        java.util.ArrayList<Long> primes = new java.util.ArrayList<>();
        long limit = (long) Math.sqrt(target);
        for (long d = 2; d <= target; d++) {
            if (target % d == 0) {
                long p = d - 1;
                if (p >= 2 && isPrime(p) && gcd(p, Ag) == 1) {
                    primes.add(p);
                }
            }
        }

        // Backtracking over subsets
        return countSubsets(primes, 0, target);
    }

    // Sum of divisors function
    private static long sigma(long n) {
        long res = 1;
        long x = n;
        for (long p = 2; p * p <= x; p++) {
            if (x % p == 0) {
                long term = 1;
                long mul = 1;
                while (x % p == 0) {
                    x /= p;
                    mul *= p;
                    term += mul;
                }
                res *= term;
            }
        }
        if (x > 1) res *= (1 + x);
        return res;
    }

    // Simple primality test for long up to around 1e12
    private static boolean isPrime(long n) {
        if (n < 2) return false;
        if (n % 2 == 0) return n == 2;
        for (long i = 3; i * i <= n; i += 2) {
            if (n % i == 0) return false;
        }
        return true;
    }

    // Count subsets of primes such that product of (1+p) equals target
    private static long countSubsets(java.util.ArrayList<Long> primes, int idx, long remaining) {
        if (remaining == 1) return 1;
        if (idx == primes.size()) return 0;

        long res = 0;
        // Skip current prime
        res += countSubsets(primes, idx + 1, remaining);

        long p = primes.get(idx);
        long factor = 1 + p;
        if (remaining % factor == 0) {
            res += countSubsets(primes, idx + 1, remaining / factor);
        }

        return res;
    }
}
