public class Main {
    // Function to compute sum of divisors of n
    private static long sumOfDivisors(long n) {
        long sum = 0;
        long limit = (long) Math.sqrt(n);
        for (long d = 1; d <= limit; d++) {
            if (n % d == 0) {
                long q = n / d;
                sum += d;
                if (q != d) sum += q;
            }
        }
        return sum;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long A = Long.parseLong(br.readLine().trim());

        long count = 0;

        // Case 1: x is odd => x = d, where d | A and d is odd, and sumDiv(d) = A
        for (long d = 1; d * d <= A; d++) {
            if (A % d == 0) {
                long d1 = d;
                long d2 = A / d;
                if ((d1 & 1) == 1 && sumOfDivisors(d1) == A) count++;
                if (d2 != d1 && (d2 & 1) == 1 && sumOfDivisors(d2) == A) count++;
            }
        }

        // Case 2: x is even => x = d * 2^k, where d | A, d is odd, k >= 1
        // For each odd divisor d of A, find k such that sumDiv(d * 2^k) = A
        for (long d = 1; d * d <= A; d++) {
            if (A % d == 0) {
                long d1 = d;
                long d2 = A / d;

                if ((d1 & 1) == 1) {
                    count += countEvenXs(A, d1);
                }
                if (d2 != d1 && (d2 & 1) == 1) {
                    count += countEvenXs(A, d2);
                }
            }
        }

        System.out.println(count);
    }

    // Count valid even x for a given odd divisor d of A
    private static long countEvenXs(long A, long d) {
        long cnt = 0;
        long S = sumOfDivisors(d);
        long t = A / d;

        // We need S * (2^(k+1) - 1) = t, k >= 1
        // So t must be divisible by S
        if (t % S != 0) return 0;
        long m = t / S; // m = 2^(k+1) - 1

        // m + 1 must be a power of two, and k >= 1 => k+1 >= 2 => exponent >= 2
        long val = m + 1;
        if (val <= 0) return 0;
        if ((val & (val - 1)) != 0) return 0; // not power of two

        int exp = Long.numberOfTrailingZeros(val);
        if ((1L << exp) != val) return 0; // safety
        int kPlus1 = exp;
        if (kPlus1 < 2) return 0; // k >= 1

        long x = d * (1L << (kPlus1 - 1));
        if (x > 0 && sumOfDivisors(x) == A) cnt++;
        return cnt;
    }
}

