        for (long d = 1; d <= limit; d++) {
            if (A % d != 0) continue;
            long s = d;
            long t = A / d; // s * t = A

            // Check if s and t have same parity
            if (((s ^ t) & 1) != 0) continue;

            long x = (s + t) / 2;
            long y = (t - s) / 2;

            if (y <= 0) continue;
            if (gcd(x, y) != 1) continue;

            count++;
        }

        System.out.println(count);
    }

